// HasEnderWith applies the HasEdge predicate on the "ender" edge with a given conditions (other predicates).
func HasEnderWith(preds ...predicate.Account) predicate.VehicleChargerPairing {
	return predicate.VehicleChargerPairing(func(s *sql.Selector) {
		step := newEnderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VehicleChargerPairing) predicate.VehicleChargerPairing {
	return predicate.VehicleChargerPairing(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VehicleChargerPairing) predicate.VehicleChargerPairing {
	return predicate.VehicleChargerPairing(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VehicleChargerPairing) predicate.VehicleChargerPairing {
	return predicate.VehicleChargerPairing(sql.NotPredicates(p))
}
